import 'dart:async';import 'package:flutter/material.dart';import '../widgets/common.dart';
class TimersScreen extends StatefulWidget{const TimersScreen({super.key});@override State<TimersScreen> createState()=>_TimersScreenState();}
class _TimersScreenState extends State<TimersScreen>{final timers=<Map<String,dynamic>>[];Timer? tick;@override void initState(){super.initState();tick=Timer.periodic(const Duration(seconds:1),(_){if(mounted)setState((){});});}@override void dispose(){tick?.cancel();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Timers')),body:timers.isEmpty?const Center(child:Text('No active timers')):ListView(children:timers.map((t){final left=(t['due'] as DateTime).difference(DateTime.now());return ListTile(leading:const Icon(Icons.timer),title:Text(t['name']),subtitle:Text(left.isNegative?'DUE':'${left.inMinutes}m ${left.inSeconds%60}s remaining'));}).toList()),floatingActionButton:FloatingActionButton(onPressed:()=>_add(c),child:const Icon(Icons.add_alarm)));
void _add(BuildContext c){final name=TextEditingController(text:'Check');final min=TextEditingController(text:'30');showDialog(context:c,builder:(x)=>AlertDialog(title:const Text('New timer'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name),TextField(controller:min,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Minutes'))]),actions:[FilledButton(onPressed:(){final m=int.tryParse(min.text)??30;setState(()=>timers.add({'name':name.text,'due':DateTime.now().add(Duration(minutes:m))}));Navigator.pop(x);},child:const Text('Start'))]));}}
